def _detect_content_format(template: str) -> str:
    """Same signal SGLang uses: multimodal keywords, or a loop over message content."""
    if any(keyword in template for keyword in ("image", "audio", "video", "vision")):
        return "openai"
    try:
        ast = jinja2.Environment().parse(template)
    except Exception:
        return "string"
    try:
        for loop in ast.find_all(jinja2.nodes.For):
            for var in ("message", "msg", "m"):
                if _jinja_access(loop.iter, var, "content"):
                    return "openai"
    except Exception:
        return "string"
    return "string"


def _jinja_access(node, varname: str, key: str | None = None) -> bool:
    if isinstance(node, (jinja2.nodes.Filter, jinja2.nodes.Test)):
        return node.node is not None and _jinja_access(node.node, varname, key)
    if isinstance(node, jinja2.nodes.Getitem) and isinstance(node.arg, jinja2.nodes.Slice):
        return _jinja_access(node.node, varname, key)
    if isinstance(node, jinja2.nodes.Name):
        return key is None and node.ctx == "load" and node.name == varname
    if isinstance(node, jinja2.nodes.Getitem):
        return (
            isinstance(node.node, jinja2.nodes.Name)
            and node.node.name == varname
            and isinstance(node.arg, jinja2.nodes.Const)
            and node.arg.value == key
        )
    if isinstance(node, jinja2.nodes.Getattr):
        return isinstance(node.node, jinja2.nodes.Name) and node.node.name == varname and node.attr == key
    return False

