def sampling_constraint(tool_parser_name: str, tools, tool_choice) -> dict:
    """Decoding constraint SGLang's chat endpoint would attach for this tool choice.

    ``auto`` gets a structural tag only when the configured SGLang detector asks for one.
    ``required`` and a named tool always get that tool's JSON schema, matching serving_chat.
    Failure leaves sampling unconstrained; the text parser still recovers tool calls.
    """
    if not tools or tool_choice in (None, "none"):
        return {}
    try:
        _, parser_cls, tool_cls = load_sglang_parsers()
        from sglang.srt.function_call.utils import get_json_schema_constraint
    except Exception:
        logger.debug("tool sampling constraint unavailable", exc_info=True)
        return {}
    try:
        tool_objs = [tool_cls.model_validate(t) for t in tools]
        choice = tool_choice
        if isinstance(tool_choice, dict):
            choice = tool_cls.model_validate({"type": "function", "function": tool_choice.get("function") or tool_choice})
            # ToolChoice lives next to Tool; model_validate on the wrong class is replaced below.
            from sglang.srt.entrypoints.openai.protocol import ToolChoice

            choice = ToolChoice.model_validate(tool_choice)
        constraint = None
        if tool_parser_name not in ("none", "glm47") and tool_parser_name in parser_cls.ToolCallParserEnum:
            constraint = parser_cls(tool_objs, tool_parser_name).get_structure_constraint(choice)
        if tool_choice == "required" or isinstance(tool_choice, dict):
            schema = get_json_schema_constraint(tool_objs, "required" if tool_choice == "required" else choice)
            if schema is not None:
                constraint = ("json_schema", schema)
        if not constraint:
            return {}
        kind, value = constraint
        if hasattr(value, "model_dump"):
            value = value.model_dump(by_alias=True)
        return {kind: value if isinstance(value, str) else json.dumps(value)}
    except Exception:
        logger.debug("tool sampling constraint failed", exc_info=True)
        return {}


