def _gen_defaults(tokenizer) -> dict:
    """Sampling defaults SGLang merges from the model's generation_config.json.

    Only keys written in that file. ``GenerationConfig.to_dict()`` also fills class defaults
    (``top_k=50``) that the chat endpoint does not send when the file leaves them unset.
    """
    path = getattr(tokenizer, "name_or_path", None) or getattr(tokenizer, "init_kwargs", {}).get("name_or_path")
    if not path:
        return {}
    cfg_path = Path(path) / "generation_config.json"
    try:
        raw = json.loads(cfg_path.read_text())
    except Exception:
        logger.debug("no generation_config at %s", path, exc_info=True)
        return {}
    if not isinstance(raw, dict):
        return {}
    return {k: raw[k] for k in ("repetition_penalty", "temperature", "top_k", "top_p", "min_p") if raw.get(k) is not None}

